import React from 'react';
import { motion } from 'framer-motion';

const Sidebar = ({ darkMode, toggleDarkMode }) => {
  const navItems = [
    { icon: 'fas fa-user', text: 'About Me' },
    { icon: 'fas fa-laptop-code', text: 'Portfolio' },
    { icon: 'fas fa-briefcase', text: 'Services & Pricing' },
    { icon: 'fas fa-file-alt', text: 'Resume' },
    { icon: 'fas fa-blog', text: 'Blog' },
    { icon: 'fas fa-envelope', text: 'Contact' },
  ];

  const socialLinks = [
    { icon: 'fab fa-twitter', href: '#' },
    { icon: 'fab fa-linkedin-in', href: '#' },
    { icon: 'fab fa-github', href: '#' },
    { icon: 'fab fa-stack-overflow', href: '#' },
    { icon: 'fas fa-paper-plane', href: '#' },
  ];

  return (
    <motion.aside
      initial={{ x: -300 }}
      animate={{ x: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
      className="w-full md:w-72 bg-primary text-white flex flex-col shrink-0 h-auto md:h-screen md:sticky md:top-0 overflow-y-auto no-scrollbar"
    >
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.2, duration: 0.5 }}
        className="flex flex-col items-center p-8 text-center"
      >
        <h2 className="text-2xl font-bold mb-4">Simon Doe</h2>
        <motion.div
          whileHover={{ scale: 1.05 }}
          transition={{ type: "spring", stiffness: 300 }}
          className="w-32 h-32 rounded-full overflow-hidden border-4 border-white/20 mb-4 shadow-lg"
        >
          <img
            alt="Profile Picture of Simon Doe"
            className="w-full h-full object-cover"
            src="https://lh3.googleusercontent.com/aida-public/AB6AXuBaqv3SY-QzHqudfBkK78zwtpyZLhlU5IYIV3Rc9siW7XwKqsyN9bks_9eX4FE-Q9hRVUcpgF0ZmsZSihrOASOZUquubZx1IGC5RRQP2n9Bjo2AveTLDJB9YNMNhjEfnN_yzObzDo4yeyoMCR8WnTCe-N7eLnJdevJcEt-rVOLCeIk-s1Kc3740P3biB71t6vFHcc9hTmcnSzVuu0eZZKg6RL8Q7exTHA5LJCaaUvAy5eV8BJ0nGBDq7RLxlPncMuYwUZ-ylzaIV_Y"
          />
        </motion.div>
        <p className="text-sm opacity-90 leading-relaxed mb-6">
          Hi, my name is Simon Doe and I'm a senior software engineer. Welcome
          to my personal website!
        </p>
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.4, duration: 0.5 }}
          className="flex space-x-3 justify-center mb-2"
        >
          {socialLinks.map((link, index) => (
            <motion.a
              key={index}
              whileHover={{ scale: 1.1, backgroundColor: 'rgba(255,255,255,0.4)' }}
              whileTap={{ scale: 0.95 }}
              className="w-8 h-8 rounded-full bg-white/20 flex items-center justify-center hover:bg-white/40 transition-colors"
              href={link.href}
            >
              <i className={`${link.icon} text-sm`}></i>
            </motion.a>
          ))}
        </motion.div>
      </motion.div>

      <nav className="flex-1 w-full px-4">
        <ul className="space-y-1">
          {navItems.map((item, index) => (
            <motion.li
              key={index}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.1 * index, duration: 0.3 }}
            >
              <motion.a
                whileHover={{ x: 5, backgroundColor: 'rgba(0,0,0,0.1)' }}
                whileTap={{ scale: 0.98 }}
                className="flex items-center space-x-3 px-4 py-3 rounded hover:bg-black/10 transition-colors font-medium"
                href="#"
              >
                <i className={`${item.icon} w-5 text-center`}></i>
                <span>{item.text}</span>
              </motion.a>
            </motion.li>
          ))}
        </ul>
      </nav>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.6, duration: 0.5 }}
        className="p-6 mt-auto space-y-6"
      >
        <motion.button
          whileHover={{ scale: 1.02, y: -2 }}
          whileTap={{ scale: 0.98 }}
          className="w-full bg-black/20 hover:bg-black/30 text-white font-bold py-3 px-4 rounded flex items-center justify-center space-x-2 transition-colors"
        >
          <i className="fas fa-paper-plane"></i>
          <span>Hire Me</span>
        </motion.button>
        
        <div className="flex flex-col items-center space-y-2">
          <span className="text-xs font-bold uppercase opacity-80">
            <i className="fas fa-adjust mr-1"></i> Dark Mode
          </span>
          <motion.button
            whileTap={{ scale: 0.95 }}
            className="relative inline-flex items-center h-6 rounded-full w-11 transition-colors focus:outline-none bg-black/30"
            onClick={toggleDarkMode}
          >
            <span className="sr-only">Enable dark mode</span>
            <motion.span
              animate={{ x: darkMode ? 4 : 24 }}
              transition={{ type: "spring", stiffness: 500, damping: 30 }}
              className="inline-block w-4 h-4 transform bg-white rounded-full"
            />
          </motion.button>
        </div>
      </motion.div>
    </motion.aside>
  );
};

export default Sidebar;
